import {registry,spells,newBuild,steps,stats,raceFor,raceTraits,replacementFor,effectiveScores,choiceEvents,eligibleOptions,calculated,spellCounts,buildIssues,previewBuild} from '../features/characters/rules/build.mjs';
import {pointSpend,standardArray,rollScores} from '../features/characters/ability-generation.mjs';
import {recordId} from './record-id.mjs';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=(id,label,current,disabled=false)=>`<option value="${e(id)}" ${id===current?'selected':''} ${disabled?'disabled':''}>${e(label)}</option>`;
const panel=(title,html)=>`<section class="rw-panel"><h2>${e(title)}</h2>${html}</section>`;
const field=(label,html)=>`<label class="rw-field"><span>${e(label)}</span>${html}</label>`;
const input=(value,attributes)=>`<input ${attributes} value="${e(value)}">`;
const check=(label,attributes,checked,help='')=>`<label class="rw-check"><input type="checkbox" ${attributes} ${checked?'checked':''}><span>${e(label)}${help?'<small>'+e(help)+'</small>':''}</span></label>`;
export function renderBuild(b,step,{query='',level='all',message='',legacy=false,mode='edit',baseline=null,displayStep=step,displaySteps=steps}={}){
 const race=raceFor(b),racial=raceTraits(b),scores=effectiveScores(b);let body='';
 if(step===0)body=`<p class="rw-source">FFD20</p>${field('Character name',input(b.name,'data-rw-field="name" maxlength="80" autocomplete="off"'))}${field('Alignment',input(b.alignment,'data-rw-field="alignment" maxlength="80"'))}${field('Biography',`<textarea data-rw-field="bio" maxlength="2000" rows="4">${e(b.bio)}</textarea>`)}${field('Portrait',`<input type="file" data-rw-portrait accept="image/png,image/jpeg,image/webp">`)}${b.portrait?'<img class="rw-portrait" src="'+e(b.portrait)+'" alt="Character portrait">':''}`;
 if(step===1)body=abilityPanel(b,{mode,baseline,legacy})+(mode==='levelup'||mode==='create'?'<div data-rw-score-spells>'+spellSlots(b,baseline)+'</div>':'');
 if(step===2){body=field('Race',`<select data-rw-field="raceId">${opt('','Choose a race',b.raceId)}${registry.races.map(r=>opt(r.id,r.name,b.raceId)).join('')}</select>`);
  if(race){body+=field('Heritage',`<select data-rw-field="heritageId">${opt('','Standard heritage',b.heritageId)}${race.data.heritages.map(h=>opt(h.id,h.name,b.heritageId)).join('')}</select>`);const h=race.data.heritages.find(h=>h.id===b.heritageId);if(h)body+='<p class="field-help">'+e(h.description)+'</p>';
   body+=panel('Standard racial traits',race.data.standardTraitIds.map(id=>{const f=race.features.find(f=>f.id===id),replaced=racial.replaced.includes(id);return `<div class="rw-trait">${check(f.name,`data-rw-trait="${id}" ${replaced?'disabled':''}`,!b.disabledTraits.includes(id),replaced?'Replaced by your selection':'Enabled by default')}<details><summary>Details</summary><p>${e(f.description)}</p></details></div>`;}).join(''));
   body+=panel('Alternate racial traits',race.data.alternateTraitIds.map(id=>{const f=race.features.find(f=>f.id===id),ops=replacementFor(race,id),available=ops.length&&ops.every(o=>o.resolution==='resolved'&&o.operation==='replace'&&o.scope==='whole_feature');return `<div class="rw-trait">${check(f.name,`data-rw-alternate="${id}" ${available?'':'disabled'}`,b.alternateIds.includes(id),available?ops.map(o=>o.description).join(' '):'Replacement mapping pending')}<details><summary>Details</summary><p>${e(f.description)}</p></details></div>`;}).join(''));
  }
 }
 if(step===3)body=panel('Black Mage',`<p>Level ${b.level}${mode==='levelup'?' · gaining one level':''}</p><p>Hit Die d6 · first level 6 HP, then 4 per level, before CON.</p><p>Skill ranks: 4 + INT modifier per level, minimum 1. No first-level ×4.</p><p>${mode==='levelup'?'Starting wealth and the outfit were granted at creation; they are not awarded again.':'Starting wealth: 70 gil plus an outfit worth up to 10 gil.'}</p>`)+field('Archetype',`<select data-rw-field="archetypeId" ${mode==='levelup'?'disabled':''}>${opt('','Base Black Mage',b.archetypeId)}${registry.archetypes.map(a=>opt(a.id,a.name+' · checking rules',b.archetypeId,true)).join('')}</select>`);
 if(step===4){body=panel('Hit points',`<p>Base Hit Die total: <strong>${b.hpRolls.slice(0,b.level).reduce((n,v)=>n+v,0)}</strong>. CON is applied once per level after ability scores are assigned.</p>`)+choiceEvents(b).filter(event=>!baseline||event.atClassLevel>baseline.level).map(event=>{const pool=registry.class.choicePools.find(p=>event.poolIds.includes(p.id)),count=calculated(event.count,b);return panel(`${pool.name} · level ${event.atClassLevel}`,Array.from({length:count},(_,i)=>{const selected=pool.options.find(o=>o.id===b.choices[event.id]?.[i]);return `<button type="button" class="rw-slot" data-rw-open-choice="${event.id}" data-choice-index="${i}"><span>${e(pool.name)} ${i+1}</span><strong>${e(selected?.name||'Choose…')}</strong><span aria-hidden="true">＋</span></button>`;}).join(''));}).join('');if(!choiceEvents(b).some(event=>!baseline||event.atClassLevel>baseline.level))body+='<p>No class choices gained at this level.</p>';}
 if(step===5)body='<p>'+(mode==='levelup'?'Choose only the new spells granted at this level. Previous learned spells are retained.':'Choose each cantrip and spell below. Extra starting spell slots are finalized from INT at the Ability scores step.')+'</p>'+spellSlots(b,baseline);
 if(step===6){const p=previewBuild(b),problems=buildIssues({...b,reviewed:true});body=`<div class="rw-preview"><h2>${e(b.name)}</h2><p>${e(race?.name)} · Black Mage ${b.level}</p><div class="rw-totals">${[['HP',p.hp],['Base MP',p.summary.baseMp],['Bonus MP',p.summary.bonusMp],['Total MP',p.summary.mp],['BAB','+'+p.summary.bab],['Fortitude',p.summary.fort+Math.floor((scores.con-10)/2)],['Reflex',p.summary.ref+Math.floor((scores.dex-10)/2)],['Will',p.summary.will+Math.floor((scores.wis-10)/2)],['Skill rank budget',p.skillBudget]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div></div>${panel('Effective ability scores','<div class="rw-score-grid">'+stats.map(k=>{const growth=Object.entries(b.abilityIncreases||{}).filter(([level,key])=>Number(level)<=b.level&&key===k).length,adjust=scores[k]-b.baseScores[k]-growth;return `<div><span>${k.toUpperCase()}</span><strong>${scores[k]}</strong><small>${b.baseScores[k]} base ${adjust>=0?'+':''}${adjust} race${growth?' +'+growth+' level':''}</small></div>`;}).join('')+'</div>')}${panel('Class features','<ul>'+p.features.map(f=>'<li>'+e(f.name)+'</li>').join('')+'</ul>')}${problems.length?'<div class="rw-notice rw-error"><strong>Still needed</strong><ul>'+problems.map(p=>'<li>'+e(p.message)+'</li>').join('')+'</ul></div>':''}<p class="field-help">Conditional bonuses and special rules remain on their ability cards. They are not added to every roll. Spells and uses should be checked before play.</p>${check('I reviewed the scores, choices and conditional rules.','data-rw-reviewed',b.reviewed)}`;}
 return `<section class="rw-wizard"><div class="rw-progress" aria-label="Character creation progress">${displaySteps.map((_,i)=>'<span class="'+(i<=displayStep?'rw-done':'')+'"></span>').join('')}</div><h1>${displaySteps[displayStep]} <small>${displayStep+1} / ${displaySteps.length}</small></h1>${message?'<p class="rw-notice rw-error" role="alert">'+e(message)+'</p>':''}${body}<p class="rw-status" data-rw-status role="status"></p><div class="wizard-actions"><button type="button" class="button" data-rw-back>${displayStep?'← Back':mode==='levelup'?'Character sheet':'Characters'}</button><button type="button" class="button primary" data-rw-next>${step===6?(mode==='levelup'?'Confirm level up':'Save & open sheet'):'Next →'}</button></div></section>`;
}
function groupedSpells(b){return b.spellSelections||{cantrips:b.spellIds.filter(id=>spells.find(s=>s.id===id)?.level===0),leveled:b.spellIds.filter(id=>spells.find(s=>s.id===id)?.level>0)};}
function spellSlots(b,baseline){
 const counts=spellCounts(b),groups=groupedSpells(b),old=baseline?spellCounts(baseline):{cantrips:0,leveled:0};
 return ['cantrips','leveled'].map(key=>panel(key==='cantrips'?'Cantrips':'Spells',`<p class="field-help">${key==='cantrips'?'Black Mage starts with 4 cantrips. INT does not add cantrips.':'First-level choices: 3 + starting INT modifier. Later levels add their own learning opportunities.'}</p>`+Array.from({length:counts[key]},(_,i)=>{if(i<old[key])return '';const id=groups[key][i],s=spells.find(s=>s.id===id);return `<button type="button" class="rw-slot" data-rw-open-spell="${key}" data-slot-index="${i}"><span>${key==='cantrips'?'Cantrip':'Spell'} ${i+1}</span><strong>${e(s?.name||'Choose…')}</strong><span aria-hidden="true">＋</span></button>`;}).join('')+(counts[key]===old[key]?'<p>No new selections at this level.</p>':'')+(groups[key].length>counts[key]?'<p class="rw-notice">There are extra selections from the previous score allocation.</p>'+groups[key].slice(counts[key]).map((id,i)=>`<button class="button" type="button" data-rw-remove-extra="${key}" data-slot-index="${counts[key]+i}">Remove ${e(spells.find(s=>s.id===id)?.name||'empty slot')}</button>`).join(''):''))).join('');
}
function abilityPanel(b,{mode,baseline,legacy}){
 const effective=effectiveScores(b);
 if(mode==='levelup')return panel('Ability increase',b.level%4===0?`<p>Character level ${b.level} grants +1 to one ability score.</p>${field('Increase one ability',`<select data-rw-boost><option value="">Choose an ability</option>${stats.map(k=>opt(k,k.toUpperCase(),b.abilityIncreases[b.level])).join('')}</select>`)}<p>Earlier milestone increases are retained. Base scores are unchanged.</p>`:'<p>No ability increase at this level. Increases occur at character levels 4, 8, 12, 16 and 20.</p>');
 const method=b.abilityMethod||'manual',pool=method==='array'?standardArray:b.scorePool||[];
 return `<p>Generate original scores, assign them, then racial adjustments are applied automatically.</p>${legacy?'<p class="rw-notice">Existing sheet values may already include racial bonuses. Use the original scores before race adjustments.</p>':''}${field('Ability score method',`<select data-rw-method>${opt('point-buy','Point buy',method)}${opt('array','Standard array',method)}${opt('rolled','Roll 4d6, drop lowest',method)}${opt('manual','Manual scores',method)}</select>`)}${method==='point-buy'?field('Point budget',`<select data-rw-budget>${[10,15,20,25].map(n=>opt(String(n),n+' points',String(b.pointBudget))).join('')}</select>`)+`<p data-rw-spent>Spent ${pointSpend(b.baseScores)} / ${b.pointBudget} points before racial adjustments.</p>`:''}${method==='rolled'?'<button class="button" type="button" data-rw-roll>Roll six scores</button><p class="field-help">Roll four d6 for each score and discard the lowest. You can rearrange the six results.</p>':''}${pool.length?'<p class="rw-dice-results">'+pool.map((v,i)=>'<span>Score '+(i+1)+': <strong>'+v+'</strong></span>').join('')+'</p>':''}<div class="rw-score-grid">${stats.map((k,i)=>field(k.toUpperCase(),(['array','rolled'].includes(method)?`<select data-rw-assign="${i}" ${pool.length!==6?'disabled':''}>${pool.map((v,j)=>opt(String(j),String(v)+' · #'+(j+1),String(b.scoreAssignments[i]))).join('')}</select>`:input(b.baseScores[k],`type="number" data-rw-score="${k}" min="${method==='point-buy'?7:1}" max="${method==='point-buy'?18:45}" step="1"`))+`<small>Total ${effective[k]} · modifier ${Math.floor((effective[k]-10)/2)>=0?'+':''}${Math.floor((effective[k]-10)/2)}</small>`)).join('')}</div><p class="field-help">Skill ranks and bonus MP are calculated after these scores. Pathfinder 1e has no first-level ×4 skill-rank multiplier.</p>`;
}
export function mountRulesWizard(){
 const main=document.querySelector('main'),control=new AbortController(),url=new URL(location.href),id=url.searchParams.get('characterId'),live=document.body.dataset.mode==='live',mode=id?(url.searchParams.get('levelUp')==='1'?'levelup':'edit'):'create';
 const order=mode==='levelup'?[3,4,5,1,6]:[0,2,3,4,5,1,6],labels=mode==='levelup'?['Next level','Class choices','Spells','Ability increase','Review']:['Identity','Race','Class','Class choices','Spells','Ability scores','Review'];
 let closed=false,b=newBuild(),baseline=null,step=0,character=null,message='',key='',draftId=recordId(),saving=false,picker=null,pickerQuery='',pickerLevel='all',pickerLimit=25;
 const dialog=document.createElement('dialog');dialog.className='rw-picker';dialog.setAttribute('aria-label','Choose a character option');document.body.append(dialog);
 function saveDraft(){if(!key)return;try{sessionStorage.setItem(key,JSON.stringify({b,step,draftId,baseRevision:character?.revision,mode}));}catch{}}
 function draw(focus=false){if(closed)return;main.innerHTML=renderBuild(b,order[step],{message,mode,baseline,displayStep:step,displaySteps:labels,legacy:Boolean(character&&!character.data.rulesBuild)});if(focus){main.querySelector('h1').setAttribute('tabindex','-1');main.querySelector('h1').focus();window.scrollTo(0,0);}}
 const changed=()=>{b.reviewed=false;message='';saveDraft();};
 function scoreFeedback(){const values=effectiveScores(b);for(const input of main.querySelectorAll('[data-rw-score]')){const value=values[input.dataset.rwScore],mod=Math.floor((value-10)/2);input.closest('label').querySelector('small').textContent='Total '+value+' · modifier '+(mod>=0?'+':'')+mod;}const spent=main.querySelector('[data-rw-spent]');if(spent)spent.textContent='Spent '+pointSpend(b.baseScores)+' / '+b.pointBudget+' points before racial adjustments.';const slots=main.querySelector('[data-rw-score-spells]');if(slots)slots.innerHTML=spellSlots(b,baseline);}

 function failure(error){message=error.message||'Could not save your build.';draw();}
 function assignPool(){const pool=b.abilityMethod==='array'?standardArray:b.scorePool;if(pool?.length===6)stats.forEach((k,i)=>b.baseScores[k]=pool[b.scoreAssignments[i]]);}
 function syncSpells(){b.spellIds=[...b.spellSelections.cantrips,...b.spellSelections.leveled].filter(Boolean);}
 function showPicker(){
  if(!picker)return;let options=[];
  if(picker.kind==='spell')options=spells.filter(s=>picker.group==='cantrips'?s.level===0:s.level>0&&s.level<=Math.min(9,Math.ceil(b.level/2))&&(pickerLevel==='all'||String(s.level)===pickerLevel));
  else options=eligibleOptions(b,picker.event).map(o=>({...o,description:[o.description,...o.featureIds.map(id=>registry.class.features.find(f=>f.id===id)?.description||'')].filter((s,i,a)=>s&&a.indexOf(s)===i).join('\n\n')}));
  options=options.filter(o=>!pickerQuery||(o.name+' '+o.description).toLowerCase().includes(pickerQuery.toLowerCase()));
  const chosen=picker.kind==='spell'?groupedSpells(b)[picker.group][picker.index]:b.choices[picker.event.id]?.[picker.index];
  dialog.innerHTML=`<div class="rw-picker-head"><h2>${picker.kind==='spell'?(picker.group==='cantrips'?'Choose a cantrip':'Choose a spell'):'Choose '+e(registry.class.choicePools.find(p=>picker.event.poolIds.includes(p.id))?.name)}</h2><button class="button" type="button" data-rw-close>Close ×</button></div><label>Find an option<input type="search" data-rw-picker-search value="${e(pickerQuery)}" placeholder="Search name or description"></label>${picker.kind==='spell'&&picker.group==='leveled'?field('Spell level',`<select data-rw-picker-level>${opt('all','All available levels',pickerLevel)}${Array.from({length:Math.min(9,Math.ceil(b.level/2))},(_,i)=>opt(String(i+1),'Level '+(i+1),pickerLevel)).join('')}</select>`):''}<div class="rw-picker-list">${options.slice(0,pickerLimit).map(o=>{const repeated=picker.kind==='choice'&&choiceEvents(b).flatMap(event=>(b.choices[event.id]||[]).filter((_,i)=>event.id!==picker.event.id||i!==picker.index)).filter(id=>id===o.id).length>=(o.repeatLimit||1);const duplicate=(picker.kind==='spell'&&b.spellIds.includes(o.id)&&o.id!==chosen)||repeated;return `<article><h3>${e(o.name)}</h3>${o.level!==undefined?'<p>Level '+o.level+' · '+o.level+' MP</p>':''}<p class="rw-full-desc">${e(o.description)}</p>${o.requirements?'<p>Prerequisites: '+e(JSON.stringify(o.requirements))+'</p>':picker.kind==='choice'?'<p class="field-help">Check prerequisites and exclusions in the feature description; this catalog is still being reviewed.</p>':''}${o.url?'<a href="'+e(o.url)+'" target="_blank" rel="noopener">Official spell reference ↗</a>':''}<button type="button" class="button ${o.id===chosen?'primary':''}" data-rw-pick="${e(o.id)}" ${duplicate?'disabled':''}>${duplicate?(picker.kind==='spell'?'Already learned':'Selection limit reached'):o.id===chosen?'Selected':'Choose '+e(o.name)}</button></article>`;}).join('')||'<p>No matching options.</p>'}</div>${options.length>pickerLimit?'<button type="button" class="button" data-rw-more>Show more options</button>':''}`;
  if(!dialog.open)dialog.showModal();
 }
 async function init(){main.innerHTML='<p role="status">Loading character builder…</p>';try{
  const r=await fetch('/api/v1/auth/session',{credentials:'same-origin',signal:control.signal,cache:'no-store'});if(!r.ok)throw Error('Sign in to create or edit a character.');const user=(await r.json()).user;if(!user)throw Error('Sign in to continue.');
  key='comos-rules-draft-v2:'+user.id+':'+(id||'new')+':'+mode;
  if(id){const response=await fetch('/api/v1/character-records/'+encodeURIComponent(id),{credentials:'same-origin',signal:control.signal,cache:'no-store'}),payload=await response.json();if(!response.ok)throw Error(payload.message||'Character unavailable.');character=payload.character;
   if(character.data.rulesBuild?.input)b={...newBuild(),...structuredClone(character.data.rulesBuild.input)};
   else{if(mode==='levelup')throw Error('Open Edit first to establish this character’s class build.');b.name=character.name;b.alignment=character.data.alignment||'';b.bio=character.data.bio||'';b.portrait=character.data.portrait||'';b.level=Math.max(1,Math.min(20,Number(character.data.level)||1));}
   if(mode==='levelup'){if(b.level>=20)throw Error('This character is already level 20.');baseline=structuredClone(b);b.level++;b.hpRolls=[...b.hpRolls,4];b.initialIntMod=baseline.initialIntMod??Math.floor((effectiveScores(baseline).int-10)/2);b.abilityIncreases={...(b.abilityIncreases||{})};b.reviewed=false;}
  }else{b.level=1;b.abilityMethod='point-buy';b.pointBudget=15;}
  b.spellSelections=groupedSpells(b);syncSpells();
  try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved?.mode===mode&&saved?.b?.version===registry.version&&saved.baseRevision===(character?.revision)&&Number.isInteger(saved.step)&&saved.step>=0&&saved.step<order.length){b=saved.b;step=saved.step;draftId=saved.draftId;}}catch{}
  draw();
 }catch(error){if(!closed)main.innerHTML='<p role="alert">'+e(error.message)+'</p><a class="button" href="'+(id?'create-identity.html?characterId='+encodeURIComponent(id):'signin.html')+'">'+(id?'Edit build':'Sign in')+'</a>';}}
 function findStep(issue){if(issue.step===1||issue.step===5)return order.indexOf(1);return Math.max(0,order.indexOf(issue.step));}
 async function finish(){if(saving)return;const found=buildIssues(b);if(found.length){step=findStep(found[0]);message=found[0].message;draw(true);return;}if(!live){message='This preview does not save real characters.';draw();return;}
  saving=true;main.querySelector('[data-rw-next]').disabled=true;main.querySelector('[data-rw-status]').textContent='Saving…';
  try{const body=id?{op:mode==='levelup'?'wizard-level-up':'wizard-build',revision:character.revision,build:b}:{build:b,requestId:draftId};const response=await fetch(id?'/api/v1/character-records/'+encodeURIComponent(id):'/api/v1/my/characters',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:control.signal});const payload=await response.json();if(!response.ok)throw Error(payload.message||'Could not save. Your draft is retained.');sessionStorage.removeItem(key);if(!closed)location.assign('sheet.html?characterId='+encodeURIComponent(payload.character.id));}catch(error){if(!closed){saving=false;failure(error);}}
 }
 main.addEventListener('input',event=>{const t=event.target;if(t.matches('[data-rw-field]'))b[t.dataset.rwField]=t.value;if(t.matches('[data-rw-score]')){b.baseScores[t.dataset.rwScore]=Number(t.value);scoreFeedback();}changed();},{signal:control.signal});
 main.addEventListener('change',async event=>{const t=event.target;try{
  if(t.matches('[data-rw-field]')){const k=t.dataset.rwField;b[k]=t.value;if(k==='raceId'){b.heritageId='';b.disabledTraits=[];b.alternateIds=[];}changed();draw();}
  if(t.matches('[data-rw-score]')){changed();draw();}
  if(t.matches('[data-rw-method]')){b.abilityMethod=t.value;b.scoreAssignments=[0,1,2,3,4,5];if(t.value==='point-buy')b.baseScores=Object.fromEntries(stats.map(k=>[k,10]));assignPool();changed();draw();}
  if(t.matches('[data-rw-budget]')){b.pointBudget=Number(t.value);changed();draw();}
  if(t.matches('[data-rw-assign]')){const i=Number(t.dataset.rwAssign),j=b.scoreAssignments.indexOf(Number(t.value)),old=b.scoreAssignments[i];b.scoreAssignments[i]=Number(t.value);if(j!==-1&&j!==i)b.scoreAssignments[j]=old;assignPool();changed();draw();}
  if(t.matches('[data-rw-boost]')){if(t.value)b.abilityIncreases[b.level]=t.value;else delete b.abilityIncreases[b.level];changed();draw();}
  if(t.matches('[data-rw-trait]')){const id=t.dataset.rwTrait;b.disabledTraits=t.checked?b.disabledTraits.filter(v=>v!==id):[...new Set([...b.disabledTraits,id])];changed();draw();}
  if(t.matches('[data-rw-alternate]')){const old=[...b.alternateIds],id=t.dataset.rwAlternate;b.alternateIds=t.checked?[...new Set([...b.alternateIds,id])]:b.alternateIds.filter(v=>v!==id);if(raceTraits(b).errors.length){b.alternateIds=old;message=raceTraits({...b,alternateIds:[...old,id]}).errors[0];draw();return;}changed();draw();}
  if(t.matches('[data-rw-reviewed]')){b.reviewed=t.checked;saveDraft();}
  if(t.matches('[data-rw-portrait]')){const file=t.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3000000)throw Error('Choose JPG, PNG or WebP under 3 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas'),ratio=Math.min(1,350/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);b.portrait=canvas.toDataURL('image/jpeg',.75);if(b.portrait.length>150000)throw Error('Try a smaller portrait.');}finally{bitmap.close();}changed();draw();}
 }catch(error){failure(error);}},{signal:control.signal});
 main.addEventListener('click',event=>{const t=event.target.closest('button');if(!t||saving)return;
  if(t.matches('[data-rw-back]')){if(step){step--;message='';saveDraft();draw(true);}else location.assign(id?'sheet.html?characterId='+encodeURIComponent(id):'characters.html');}
  if(t.matches('[data-rw-next]')){if(order[step]===6){void finish();return;}const logical=order[step],issues=buildIssues(b).filter(i=>logical===1?[1,5].includes(i.step):i.step===logical&&logical!==5);if(issues.length){message=issues[0].message;draw();return;}if(mode==='levelup'&&logical===1&&b.level%4===0&&!b.abilityIncreases[b.level]){message='Choose one ability to increase by +1.';draw();return;}step++;message='';saveDraft();draw(true);}
  if(t.matches('[data-rw-roll]')){const rolled=rollScores();b.scorePool=rolled.map(r=>r.total);b.scoreAssignments=[0,1,2,3,4,5];assignPool();changed();draw();}
  if(t.matches('[data-rw-open-spell]')){picker={kind:'spell',group:t.dataset.rwOpenSpell,index:Number(t.dataset.slotIndex)};pickerQuery='';pickerLevel='all';pickerLimit=25;showPicker();}
  if(t.matches('[data-rw-open-choice]')){picker={kind:'choice',event:choiceEvents(b).find(ev=>ev.id===t.dataset.rwOpenChoice),index:Number(t.dataset.choiceIndex)};pickerQuery='';pickerLevel='all';pickerLimit=25;showPicker();}
  if(t.matches('[data-rw-remove-extra]')){b.spellSelections[t.dataset.rwRemoveExtra].splice(Number(t.dataset.slotIndex),1);syncSpells();changed();draw();}
 },{signal:control.signal});
 dialog.addEventListener('change',event=>{if(event.target.matches('[data-rw-picker-level]')){pickerLevel=event.target.value;pickerLimit=25;showPicker();}},{signal:control.signal});
 dialog.addEventListener('input',event=>{if(event.target.matches('[data-rw-picker-search]')){pickerQuery=event.target.value;pickerLimit=25;showPicker();const search=dialog.querySelector('[data-rw-picker-search]');search.focus();search.setSelectionRange(pickerQuery.length,pickerQuery.length);}},{signal:control.signal});
 dialog.addEventListener('click',event=>{const t=event.target.closest('button');if(!t)return;if(t.matches('[data-rw-close]'))dialog.close();if(t.matches('[data-rw-more]')){pickerLimit+=25;showPicker();}if(t.matches('[data-rw-pick]')){if(picker.kind==='spell'){b.spellSelections[picker.group][picker.index]=t.dataset.rwPick;syncSpells();}else{b.choices[picker.event.id]??=[];b.choices[picker.event.id][picker.index]=t.dataset.rwPick;}dialog.close();changed();draw();}},{signal:control.signal});
 void init();return ()=>{closed=true;control.abort();dialog.remove();};
}
